def test_DashSegmentsFD_real_download(monkeypatch, tmp_path):
    fd = DashSegmentsFD.__new__(DashSegmentsFD)
    fd.params = {
        'fragment_retries': 2,
        'skip_unavailable_fragments': True,
    }

    downloaded_urls = []
    appended_fragments = []
    retries = []
    attempts = {}
    finished_contexts = []

    def prepare(ctx):
        ctx['fragment_index'] = 0

    def download_fragment(ctx, fragment_url, info_dict):
        downloaded_urls.append(fragment_url)
        attempts[fragment_url] = attempts.get(fragment_url, 0) + 1

        # Simulate a transient HTTP error for the initialization segment.
        if fragment_url.endswith('init.m4s') and attempts[fragment_url] == 1:
            raise compat_urllib_error.HTTPError(
                fragment_url, 404, 'Not Found', {}, None)

        return True, fragment_url.encode('utf-8')

    def append_fragment(ctx, content):
        appended_fragments.append(content)
        ctx['fragment_index'] += 1

    def report_retry(error, fragment_index, retry_count, max_retries):
        retries.append((error.code, fragment_index, retry_count, max_retries))

    def finish(ctx):
        finished_contexts.append(dict(ctx))

    monkeypatch.setattr(fd, '_prepare_and_start_frag_download', prepare)
    monkeypatch.setattr(fd, '_download_fragment', download_fragment)
    monkeypatch.setattr(fd, '_append_fragment', append_fragment)
    monkeypatch.setattr(fd, 'report_retry_fragment', report_retry)
    monkeypatch.setattr(fd, '_finish_frag_download', finish)

    info_dict = {
        'fragment_base_url': 'https://example.com/media/',
        'fragments': [
            {'path': 'init.m4s'},
            {'url': 'https://cdn.example.com/segment-1.m4s'},
        ],
    }
    filename = str(tmp_path / 'video.mp4')

    assert fd.real_download(filename, info_dict) is True

    assert downloaded_urls == [
        'https://example.com/media/init.m4s',
        'https://example.com/media/init.m4s',
        'https://cdn.example.com/segment-1.m4s',
    ]
    assert retries == [(404, 1, 1, 2)]
    assert appended_fragments == [
        b'https://example.com/media/init.m4s',
        b'https://cdn.example.com/segment-1.m4s',
    ]
    assert finished_contexts == [{
        'filename': filename,
        'total_frags': 2,
        'fragment_index': 2,
    }]
